<script setup>
import { computed } from 'vue'
import { RouterLink } from 'vue-router'
import { products, formatIDR } from '../data/products'
import { useCartStore } from '../stores/cart'
const cart=useCartStore(),saved=computed(()=>products.filter(p=>cart.wishlist.includes(p.id)))
</script>
<template><div class="wishlist-page"><div class="breadcrumbs"><RouterLink to="/">Beranda</RouterLink><span>/</span><b>Favorit</b></div><div class="cart-title"><div><span class="section-index">DISIMPAN UNTUK NANTI</span><h1>Kopi favorit<span>.</span></h1></div><span>{{ saved.length }} KOPI</span></div><div v-if="saved.length" class="shop-product-grid wishlist-grid"><article v-for="product in saved" :key="product.id" class="product-card"><div class="product-image-wrap"><RouterLink :to="`/product/${product.id}`" class="product-image-link"><img :src="product.image" :alt="product.name"/><span class="image-origin">{{ product.region }} <i>↗</i></span></RouterLink><button class="favorite-button saved" aria-label="Hapus dari favorit" @click="cart.toggleWishlist(product.id)"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8l1.1 1.1L12 21l7.8-7.5 1.1-1.1a5.5 5.5 0 0 0-.1-7.8Z"/></svg></button></div><div class="product-meta"><span>{{ product.process }}</span><span>{{ product.roastLabel }}</span></div><RouterLink :to="`/product/${product.id}`" class="product-title">{{ product.name }}</RouterLink><p class="product-origin">{{ product.origin }}</p><div class="product-card-foot"><span><b>{{ formatIDR(product.price) }}</b><small> / 250g</small></span><button :aria-label="`Tambah ${product.name}`" @click="cart.add(product.id)">+</button></div></article></div><div v-else class="cart-empty"><div class="empty-illustration"><span>♡</span></div><span class="section-index">BELUM ADA KOPI TERSIMPAN</span><h2>Rasa yang disuka<br/><em>layak diingat.</em></h2><p>Simpan kopi yang menarik perhatianmu, lalu kembali kapan saja.</p><RouterLink to="/shop" class="button button-dark">Jelajahi origin <span>↗</span></RouterLink></div></div></template>
